const bank={
 synonyms:[['BRILLIANT','Genius, dazzling','Radiant'],['ANCIENT','Old, ancient','Modern'],['ENORMOUS','Huge','Tiny'],['TINY','Minute','Huge'],['CALM','Peaceful','Agitated'],['RAPID','Swift','Slow'],['SILENT','Quiet','Noisy'],['BOLD','Courageous','Shy'],['SCARCE','Rare','Common'],['HAPPY','Joyful','Sad']],
 antonyms:[['BRAVE','Cowardly','Courageous'],['GENEROUS','Selfish','Kind'],['BEGIN','Finish','Start'],['ASCEND','Descend','Climb'],['DENSE','Sparse','Thick'],['MEEK','Aggressive','Humble'],['PRESENT','Absent','Existing'],['PROSPER','Fail','Thrive'],['TRANSPARENT','Opaque','Clear'],['WEAK','Strong','Frail']],
 spelling:[['CORRECT','CORRECT','CORRECTE'],['AWARE','AWARE','AWWARE'],['NOTICE','NOTICE','NOTISE'],['BEAUTIFUL','BEAUTIFUL','BEUTIFUL'],['RECEIVE','RECEIVE','RECIEVE'],['IMPORTANT','IMPORTANT','IMPORTENT'],['KNOWLEDGE','KNOWLEDGE','KNOWLEGE'],['QUESTION','QUESTION','QUSTION'],['SUCCESS','SUCCESS','SUCESS'],['ADDRESS','ADDRESS','ADRESS']]
};
Object.keys(bank).forEach(k=>bank[k].forEach(r=>{r._answer=r[1];r._options=[r[1],r[2],r[2]===r[1]?'Incorrect':r[1]+'ish','Opposite'];r._options=[...new Set(r._options)].slice(0,4)}));
let state={mode:'mixed',i:0,correct:0,lives:3,questions:[],answered:false,points:Number(localStorage.points||0),streak:Number(localStorage.streak||0),sessions:Number(localStorage.sessions||0),sound:true};
const $=s=>document.querySelector(s);function show(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id).classList.add('view')?.};
function showView(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id).classList.add('active')}
function updateStats(){ $('#pointsTop').textContent=state.points;$('#streakTop').textContent=state.streak;const pct=Math.min(100,state.sessions*10);$('#progressFill').style.width=pct+'%';$('#progressPct').textContent=pct+'%';$('#levelLabel').textContent=pct<40?'Beginner · Level 1':pct<70?'Explorer · Level 2':'Master · Level 3'}
updateStats();
function shuffle(a){return [...a].sort(()=>Math.random-.5)}
function makeQuestions(mode){let source=[];if(mode==='mixed')Object.values(bank).forEach(a=>source.push(...a));else source=bank[mode];return shuffle(source).slice(0,10).map(r=>({word:r[0],answer:r._answer,options:shuffle(r._options),type:mode==='mixed'?(bank.synonyms.includes(r)?'synonyms':bank.antonyms.includes(r)?'antonyms':'spelling':mode)}))}
function start(mode){state.mode=mode;state.i=0;state.correct=0;state.lives=3;state.questions=makeQuestions(mode);showView('#gameView');renderQuestion()}
function typeLabel(t){return t==='synonyms'?'CHOOSE THE SYNONYM':t==='antonyms'?'CHOOSE THE ANTONYM':t==='spelling'?'CHOOSE CORRECT SPELLING':'VOCABULARY'}
function renderQuestion(){if(state.i>=10||state.lives<=0)return finish();const q=state.questions[state.i];state.answered=false;$('#category').textContent=typeLabel(q.type);$('#prompt').textContent=q.type==='synonyms'?'Choose the closest meaning':q.type==='antonyms'?'Choose the opposite meaning':q.type==='spelling'?'Which spelling is correct?':'Choose the closest meaning';$('#word').textContent=q.word;$('#questionCount').textContent=`${state.i+1} / 10`;$('#gameProgress').style.width=`${((state.i+1)/10)*100}%`;$('#lives').textContent='♥ '.repeat(state.lives).trim();$('#nextBtn').disabled=true;const wrap=$('#answers');wrap.innerHTML='';q.options.forEach(opt=>{const b=document.createElement('button');b.className='answer';b.textContent=opt;b.onclick=()=>choose(b,opt,q);wrap.appendChild(b)})}
function choose(btn,opt,q){if(state.answered)return;state.answered=true;document.queryAll=undefined;document.querySelectorAll('.answer').forEach(b=>b.disabled=true);if(opt===q.answer){btn.classList.add('correct');state.correct++;tone(660)}else{btn.classList.add('wrong');state.lives--;tone(180);document.querySelectorAll('.answer').forEach(b=>{if(b.textContent===q.answer)b.classList.add('correct')})}$('#lives').textContent='♥ '.repeat(state.lives).trim();$('#nextBtn').disabled=false}
function tone(freq){if(!state.sound)return;const ctx=new(window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.05,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12)}
function next(){state.i++;renderQuestion()}
function finish(){const acc=Math.round(state.correct/Math.max(1,state.i||10)*100);const earned=state.correct*10;state.points+=earned;state.sessions++;if(state.correct>=state.i*.7)state.streak++;else state.streak=0;localStorage.points=state.points;localStorage.streak=state.streak;localStorage.sessions=state.sessions;updateStats();$('#correctResult').textContent=state.correct;$('#accuracyResult').textContent=acc+'%';$('#pointsResult').textContent='+'+earned;$('#resultTitle').textContent=acc>=80?'Outstanding!':acc>=50?'Great work!':'Keep practicing!';$('#resultMessage').textContent=acc>=80?'You truly know your words.':acc>=50?"You're building a stronger vocabulary.":'Every master starts with a single word.';showView('#resultView')}
function speak(){const q=state.questions[state.i];if('speechSynthesis' in window)speechSynthesis.speak(new SpeechSynthesisUtterance(q.word))}
document.querySelectorAll('.mode-card').forEach(b=>b.onclick=()=>start(b.dataset.mode));$('#backBtn').onclick=()=>showView('#homeView');$('#homeBtn').onclick=()=>showView('#homeView');$('#resultHomeBtn').onclick=()=>showView('#homeView');$('#againBtn').onclick=()=>start(state.mode);$('#nextBtn').onclick=next;$('#speakBtn').onclick=speak;$('#soundBtn').onclick=()=>{state.sound=!state.sound;$('#soundBtn').style.opacity=state.sound?'1':'.35'};

